def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Function f that divides out all factors of k
    def f(x):
        while x % k == 0:
            x //= k
        return x

    # Sort to have consistent state representation
    a = sorted(a)

    # Check if it's possible
    # We'll use recursion with state: bitmask of remaining numbers
    # Also track the current multiset of numbers

    memo = {}
    target = 1

    from functools import lru_cache

    def get_tuple(arr):
        return tuple(sorted(arr))

    def reachable(arr):
        state = get_tuple(arr)
        if state in memo:
            return memo[state]

        if len(arr) == 1 and arr[0] == 1:
            memo[state] = True
            return True

        if len(arr) == 0:
            memo[state] = False
            return False

        # Need to combine 2 numbers -> len-1 numbers
        if len(arr) == 1:
            memo[state] = False
            return False

        for i in range(len(arr)):
            for j in range(i + 1, len(arr)):
                x, y = arr[i], arr[j]
                new_val = f(x + y)
                new_arr = arr[:i] + arr[i+1:j] + [new_val] + arr[j+1:]
                if reachable(new_arr):
                    memo[state] = True
                    return True

        memo[state] = False
        return False

    if reachable(a):
        # Need to reconstruct the solution
        # Redo with solution tracking

        def solve_with_path(arr):
            state = get_tuple(arr)
            if state in memo:
                return None

            if len(arr) == 1 and arr[0] == 1:
                memo[state] = []
                return []

            if len(arr) <= 1:
                memo[state] = None
                return None

            for i in range(len(arr)):
                for j in range(i + 1, len(arr)):
                    x, y = arr[i], arr[j]
                    new_val = f(x + y)
                    new_arr = arr[:i] + arr[i+1:j] + [new_val] + arr[j+1:]

                    path = solve_with_path(new_arr)
                    if path is not None:
                        memo[state] = [(x, y)] + path
                        return [(x, y)] + path

            memo[state] = None
            return None

        path = solve_with_path(a)
        if path is not None:
            result = ['YES']
            for x, y in path:
