    h2, m2 = map(int, lines[2].split())

    h_digits = len(str(h - 1))
    m_digits = len(str(m - 1))

    def format_time(val, digits):
        return str(val).zfill(digits)

    def count_changes(val1, digits1, val2, digits2):
        if val1 == val2 and val1 % 10 == 0 and m % 10 == 0:
            return 0
        return sum(1 for i in range(digits1) if format_time(val1 % (10**(i+1)), digits1)[:1] != 
                     format_time(val2 % (10**(i+1)), digits2)[:1])

    changes = 0
    current_h, current_m = h1, m1
    visited = set()

    while True:
        next_m = current_m + 1
        next_h = current_h
        if next_m >= m:
            next_m = 0
            next_h = next_h + 1
            if next_h >= h:
                next_h = 0

        # Check if this next state is within the range (exclusive of h2:m2 -> next)
        if next_h > h2 or (next_h == h2 and next_m > m2):
            break

        # Count digit changes between current and next
        diff = 0
        for i in range(h_digits):
            ch = (current_h // (10**i)) % 10
            nh = (next_h // (10**i)) % 10
            if ch != nh:
                diff += 1
        for i in range(m_digits):
            cm = (current_m // (10**i)) % 10
            nm = (next_m // (10**i)) % 10
            if cm != nm:
                diff += 1

        if diff >= k:
            changes += 1

        current_h, current_m = next_h, next_m

        if (current_h, current_m) in visited:
            break
        visited.add((current_h, current_m))

    return str(changes) + '\n'
