Looking at this problem, I need to count squares in a 0-1 matrix. There are two types:
1. Axis-aligned squares (sides parallel to matrix sides)
2. Diagonal squares (sides parallel to diagonals)

A square must:
- Be a border of 1s with linewidth 1 (interior can be 0 or 1)
- Be at least 2×2
- Not touch any foreign 1s (by side or corner)

Let me write the solution:

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        grid = [[1 if ch == '1' else 0 for ch in lines[idx]] for idx in range(idx, idx + n)]
        idx += n

        count = 0

        # Check axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r0 in range(n - size + 1):
                for c0 in range(m - size + 1):
                    # Check if valid axis-aligned square
                    valid = True

                    # Check top and bottom borders
                    for j in range(size):
                        if grid[r0][c0 + j] != 1 or grid[r0 + size - 1][c0 + j] != 1:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check left and right borders
                    for i in range(size):
                        if grid[r0 + i][c0] != 1 or grid[r0 + i][c0 + size - 1] != 1:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check no foreign 1s touching the border
                    for r in range(max(0, r0 - 1), min(n, r0 + size)):
                        for c in range(max(0, c0 - 1), min(m, c0 + size)):
                            if (r0 <= r <= r0 + size - 1 and c0 <= c <= c0 + size - 1) and grid[r][c] == 1:
                                continue  # Part of the square
                            if abs(r - r0) + abs(c - c0) == size:  # Touching the border
                                if grid[r][c] != 0:
                                    valid = False
                                    break
                        if not valid:
                            break
                    if valid:
                        count += 1

        # Check diagonal squares
        # For diagonal squares, use diamond pattern with Manhattan distance
        for size in range(2, min(n, m) + 1):
            # For a diamond pattern, calculate valid center positions
            for r in range(n):
                for c in range(m):
                    # Can a square of size 'size' be centered here?
                    if 2 - size % 2 > 0:  # Only odd diameters possible
                        continue

                    max_dist = (size - 1) // 2

                    # Check all cells within Manhattan distance
                    valid = True
                    for rchk in range(max(0, r - max_dist), min(n, r + max_dist + 1)):
                        for cchk in range(max(0, c - max_dist), min(m, c + max_dist + 1)):
                            dist = abs(rchk - r) + abs(cchk - c)

                            if dist == max_dist:
                                # Border cell - must be 1
                                if grid[rchk][cchk] != 1:
                                    valid = False
                                    break
                            elif dist < max_dist:
                                # Interior cell - must be 0
                                if grid[rchk][cchk] != 0:
                                    valid = False
                                    break
                            # dist > max_dist: outside, can be anything
                            elif dist == 1:
                                # Adjacent to center - must be 0 (touching diagonal)
                                pass
                        if not valid:
                            break
                    if not valid:
                        continue

                    # Check for foreign 1s touching the border
                    for rchk in range(max(0, r - max_dist - 1), min(n, r + max_dist + 2)):
                        for cchk in range(max(0, c - max_dist - 1), min(m, c + max_dist + 2)):
                            if dist := abs(rchk - r) + abs(cchk - c) <= max_dist + 1:
                                if dist > max_dist and grid[rchk][cchk] == 1:
                                    valid = False
                                    break
                        if not valid:
                            break
                    if valid:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)
