        """
        Count how many edges of the ring are strictly between a and b
        counting in one direction.
        """
        a, b = normalize_pair(a, b)
        if a == b:
            return 0
        # Count edges from a+1 to b-1
        return (b - 1) - (a + 1) + 1  # Number of internal vertices
        # Actually, we need to count ring edges strictly between them
        # Ring edges are (i, i+1) for i in 1..n-1, and (n, 1)

    def count_edges_between(a, b, clockwise):
        """Count number of ring edges strictly between city a and city b"""
        if clockwise:
            # Going from a to b clockwise (a->a+1->...->b)
            if a < b:
                return b - a - 1
            else:
                return n - a - 1 + b - 1  # a to n, then n to 1, then 1 to b
        else:
            # Going from a to b counterclockwise
            if a > b:
                return a - b - 1
            else:
                return a - 1 + n - b - 1

    # Build conflict graph
    # Two roads conflict if they cross inside the ring
    # We need to assign each road either 'I' or 'O' (inside or outside)
    # Roads that cross must have different assignments

    def roads_cross(a1, b1, a2, b2):
        """
