        Two chords cross if their endpoints alternate around the circle.
        """
        a1, b1 = normalize_pair(a1, b1)
        a2, b2 = normalize_pair(a2, b2)

        # For proper crossing: endpoints must alternate
        # Check if one endpoint of road 2 is between a1 and b1, 
        # and the other is not

        def is_between(a, b, x):
            """Check if x is strictly between a and b (going clockwise from a to b)"""
            if a == b:
                return False
            a1, b1_val = normalize_pair(a, b)
            if a1 < b1_val:
                return a1 < x < b1_val
            else:
                return x < a1 or x > b1_val

        # Check if a2 is between a1 and b1 (clockwise)
        between_a2 = is_between(a1, b1, a2)
        between_b2 = is_between(a1, b1, b2)

        # They cross if exactly one endpoint is between
        return between_a2 != between_b2

    # Build adjacency list for conflict graph
    adj = [[] for _ in range(m)]

    for i in range(m):
        a1, b1 = roads[i]
        for j in range(i + 1, m):
            a2, b2 = roads[j]
            if roads_cross(a1, b1, a2, b2):
                adj[i].append(j)
                adj[j].append(i)

    # Try to 2-color the conflict graph
    color = {}
    valid = True

    def dfsConflict(u):
        nonlocal valid
        if valid is False:
            return
        for v in adj[u]:
            if v not in color:
                color[v] = 1 - color[u]
