    return '\n'

def parse_input(input_data):
    """Parse input to extract board and settings."""
    lines = input_data.strip().split('\n')
    idx = 0

    first_part = lines[idx].split()
    n, m = int(first_part[0]), int(first_part[1])

    # Check for swap flags
    if len(first_part) > 2:
        swapLR = int(first_part[2])
        swapUD = int(first_part[3])
    else:
        swapLR = 0
        swapUD = 0

    idx += 1
    board = []
    for i in range(n):
        board.append(list(lines[idx + i]))

    # Find start and finish
    start = (0, 0)
    finish = None
    for i in range(n):
        for j in range(m):
            if board[i][j] == 'F':
                finish = (i, j)
                break

    return n, m, swapLR, swapUD, board, start, finish

def find_path_with_swaps(board, start, finish, swapLR, swapUD):
    """BFS to find path with given swap settings."""
    # Map buttons to directions after swaps
    # Button 0=L, 1=R, 2=U, 3=D
    # After LR swap: 0 becomes R, 1 becomes L
    # After UD swap: 2 becomes D, 3 becomes U

    if swapLR:
        # L button goes Right, R button goes Left
        btn_to_dir = {0: (0, 1), 1: (0, -1), 2: (-1, 0), 3: (1, 0)}
    elif swapUD:
        # U button goes Down, D button goes Up
        btn_to_dir = {0: (0, -1), 1: (0, 1), 2: (1, 0), 3: (-1, 0)}
    elif swapLR and swapUD:
        # Both swaps
        btn_to_dir = {0: (0, 1), 1: (0, -1), 2: (1, 0), 3: (-1, 0)}
    else:
        # No swaps - standard directions
        btn_to_dir = {0: (0, -1), 1: (0, 1), 2: (-1, 0), 3: (1, 0)}

    queue = deque([(start[0], start[1], [])])
    visited = {(0, 0)}

    while queue:
        r, c, path = queue.popleft()

        if (r, c) == finish:
            return path

        for btn, (dr, dc) in btn_to_dir.items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and board[nr][nc] != '*' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, path + [btn]))

    return None

