    # Build output based on swap settings
    # If swapLR: button 0=R, button 1=L
    # If swapUD: button 2=D, button 3=U
    # Otherwise: 0=L, 1=R, 2=U, 3=D

    if swapLR and swapUD:
        btn_map = {0: 'R', 1: 'L', 2: 'D', 3: 'U'}
    elif swapLR:
        btn_map = {0: 'R', 1: 'L', 2: 'U', 3: 'D'}
    elif swapUD:
        btn_map = {0: 'L', 1: 'R', 2: 'D', 3: 'U'}
    else:
        btn_map = {0: 'L', 1: 'R', 2: 'U', 3: 'D'}

    result = []
    for btn in path:
        result.append(btn_map[btn])

    return '\n'.join(result)

