    MOD = 10**9 + 7
    MAX_N = 1000000
    MAX_COMB = 2000000

    # Precompute SPF (smallest prime factor) using sieve
    spf = list(range(MAX_N + 1))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute factorials
    fact = [1] * (MAX_COMB + 1)
    inv = [1] * (MAX_COMB + 1)

    for i in range(1, MAX_COMB + 1):
        fact[i] = (fact[i-1] * i) % MOD

    inv[MAX_COMB] = power(fact[MAX_COMB], MOD - 2, MOD)
    for i in range(MAX_COMB - 1, -1, -1):
        inv[i] = (inv[i+1] * (i + 1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n-r] % MOD

    # f_r(p^e) = C(e+r, r) + C(e+r-1, r) for e >= 1
    def f_r_for_prime_power(exp, r):
        if exp == 0:
            return 1
        return (nCr(exp + r, r) + nCr(exp + r - 1, r)) % MOD

    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    results = []

    for i in range(1, q + 1):
        parts = lines[i].split()
