        n = int(parts[1])

        if n == 1:
            results.append('1')
            continue

        ans = 1
        temp = n

        # Factorize using SPF
        while temp > 1:
            p = spf[temp]
            exp = 0
            while temp % p == 0:
                exp += 1
                temp //= p
            ans = (ans * f_r_for_prime_power(exp, r)) % MOD

        results.append(str(ans))

    return '\n'.join(results)
