        row_str = lines[i + 1]
        row_vals = list(map(int, row_str.split()))

        # Create list of (city_idx, cost) for all other cities in groups
        all_cities = list(range(n))
        all_cities.remove(i)  # Remove self

        # Each value in row corresponds to city order 0,1,2,...,n-2 (skipping i)
        for j, city_idx in enumerate(all_cities):
            costs[i][city_idx] = row_vals[j]

    # Function to check if a matching is stable
    def is_stable(matching):
        for i in range(n):
            partner_i = matching[i]
            for j in range(n):
                partner_j = matching[j]
                # Check if (i,j) is a blocking pair
                # i not with j, j not with i, and both would prefer each other
                if partner_i != j and partner_j != i:
                    if costs[i][j] < costs[i][partner_i] and costs[j][i] < costs[j][partner_j]:
                        return False
        return True

    # Generate all possible perfect matchings for small N
    if n <= 12:
        def generate_matchings(used, pairs):
            """Generate all perfect matchings recursively"""
            if len(used) == n:
                yield pairs[:]
                return

            # Find first unpaired city
            i = 0
            while i < n and used[i]:
                i += 1

            # Try pairing i with all available cities j > i
            for j in range(i + 1, n):
                if not used[j]:
                    used[i] = used[j] = True
                    pairs.append((i, j))
                    yield from generate_matchings(used, pairs)
                    pairs.pop()
