def solution(input_str):
    parts = input_str.split()
    n, k, x = int(parts[0]), int(parts[1]), int(parts[2])
    a = [int(v) for v in parts[3:]]

    # Create list with original indices and sort by absolute value
    indexed = list(enumerate(a))
    indexed.sort(key=lambda p: abs(p[1]))

    operations = k
    result = [0] * n

    for i, original_idx in indexed:
        if operations == 0:
            result[original_idx] = a[i]
            continue

        val = a[i]

        if val == 0:
            result[original_idx] = 0
            operations -= 1
        elif abs(val) % x == 0 and abs(val) // x == 1:
            # val is exactly x in absolute value
            if val == x:
                result[original_idx] = 0
            elif val == -x:
                result[original_idx] = 0
            operations -= 1
        elif abs(val) % x == 0 and abs(val) // x >= 1:
            # val is divisible by x, can reduce to 0
            if abs(val) // x > 1:
                result[original_idx] = 0
                operations -= 1
        elif abs(val) < x:
            # val has smaller absolute value than x
            # Change sign to make it closer to zero or away
            if val >= 0:
                result[original_idx] = val - x
            else:
                result[original_idx] = val + x
            operations -= 1
        else:
            # Reduce to nearest multiple of x
            if val > 0:
                result[original_idx] = val - (val % x)
            else:
                result[original_idx] = val + (abs(val) % x)
            operations -= 1

    return ' '.join(map(str, result)) + '\n'


